package com.arqly.backend.notification;
import com.arqly.backend.entity.*;import com.arqly.backend.repository.TenantUserRepository;import java.util.*;import java.util.regex.*;import org.springframework.stereotype.Component;
@Component public class NotificationDomainPublisher {private final NotificationEventPublisher events;private final NotificationActionResolver actions;private final TenantUserRepository users;public NotificationDomainPublisher(NotificationEventPublisher events,NotificationActionResolver actions,TenantUserRepository users){this.events=events;this.actions=actions;this.users=users;}
 public void stageAssigned(ProjectStage stage){var recipient=stage.getResponsibleUser();if(recipient==null)return;var project=stage.getProjectPhase().getProject();send(project.getTenant().getId(),recipient.getId(),NotificationType.ASSIGNMENT,NotificationCategory.PROJECT,NotificationPriority.HIGH,"Nova etapa atribuída","Você foi atribuído à etapa "+stage.getName()+" em "+project.getName()+".",NotificationSourceType.PROJECT_STAGE,stage.getId(),actions.resolve(NotificationSourceType.PROJECT_STAGE,project.getId(),stage.getId()),"assignment:"+stage.getId()+":"+recipient.getId(),false);}
 public void mentions(ProjectStage stage,String comment,UUID authorId){if(comment==null||comment.isBlank())return;var project=stage.getProjectPhase().getProject();var candidates=users.findAllByTenantIdAndActiveTrueOrderByNameAsc(project.getTenant().getId());var matcher=Pattern.compile("@([\\p{L}\\p{N}._-]+)").matcher(comment);Set<UUID> recipients=new LinkedHashSet<>();while(matcher.find()){String token=matcher.group(1).toLowerCase();candidates.stream().filter(u->!u.getId().equals(authorId)&&(u.getEmail().toLowerCase().startsWith(token)||u.getName().toLowerCase().replace(" ",".").equals(token)||u.getName().toLowerCase().replace(" ","").equals(token))).forEach(u->recipients.add(u.getId()));}for(var id:recipients)send(project.getTenant().getId(),id,NotificationType.MENTION,NotificationCategory.COLLABORATION,NotificationPriority.NORMAL,"Você foi mencionado",comment,NotificationSourceType.PROJECT_STAGE,stage.getId(),actions.resolve(NotificationSourceType.PROJECT_STAGE,project.getId(),stage.getId()),"mention:"+stage.getId()+":"+id+":"+Integer.toHexString(comment.hashCode()),false);}
 public void approvalRejected(Approval approval){var project=approval.getProject();Set<TenantUser> recipients=new LinkedHashSet<>();if(project.getResponsibleUser()!=null)recipients.add(project.getResponsibleUser());if(approval.getStage()!=null&&approval.getStage().getResponsibleUser()!=null)recipients.add(approval.getStage().getResponsibleUser());for(var user:recipients)send(project.getTenant().getId(),user.getId(),NotificationType.APPROVAL_REJECTED,NotificationCategory.APPROVAL,NotificationPriority.HIGH,"Aprovação requer ajustes","O cliente solicitou ajustes em: "+approval.getDescription()+".",NotificationSourceType.APPROVAL,approval.getId(),actions.resolve(NotificationSourceType.APPROVAL,project.getId(),approval.getId()),"approval-rejected:"+approval.getId()+":"+user.getId(),false);}
 public void criticalOccurrence(ConstructionDiaryOccurrence occurrence){if(occurrence.getSeverity()!=ConstructionDiarySeverity.CRITICAL)return;var project=occurrence.getDiaryEntry().getProject();Set<TenantUser> recipients=new LinkedHashSet<>();if(project.getResponsibleUser()!=null)recipients.add(project.getResponsibleUser());if(occurrence.getResponsibleUser()!=null)recipients.add(occurrence.getResponsibleUser());for(var user:recipients)send(project.getTenant().getId(),user.getId(),NotificationType.DIARY_CRITICAL_OCCURRENCE,NotificationCategory.DIARY,NotificationPriority.CRITICAL,"Ocorrência crítica registrada",occurrence.getTitle(),NotificationSourceType.DIARY_OCCURRENCE,occurrence.getId(),actions.resolve(NotificationSourceType.CONSTRUCTION_DIARY,project.getId(),occurrence.getDiaryEntry().getId()),"critical-occurrence:"+occurrence.getId()+":"+user.getId(),true);}
 public void reminder(ProjectStage stage){var project=stage.getProjectPhase().getProject();var user=stage.getResponsibleUser()!=null?stage.getResponsibleUser():project.getResponsibleUser();if(user==null)return;send(project.getTenant().getId(),user.getId(),NotificationType.STAGE_DUE_SOON,NotificationCategory.CALENDAR,NotificationPriority.NORMAL,"Prazo de etapa se aproxima",stage.getName()+" vence em breve.",NotificationSourceType.PROJECT_STAGE,stage.getId(),actions.resolve(NotificationSourceType.PROJECT_STAGE,project.getId(),stage.getId()),"stage-due:"+stage.getId()+":"+stage.getPlannedEnd()+":"+user.getId(),false);}
 public void visitReminder(ConstructionDiaryEntry entry){var user=entry.getResponsibleUser()!=null?entry.getResponsibleUser():entry.getProject().getResponsibleUser();if(user==null)return;send(entry.getTenant().getId(),user.getId(),NotificationType.CALENDAR_REMINDER,NotificationCategory.CALENDAR,NotificationPriority.NORMAL,"Visita prevista para amanhã",entry.getTitle(),NotificationSourceType.CONSTRUCTION_DIARY,entry.getId(),actions.resolve(NotificationSourceType.CONSTRUCTION_DIARY,entry.getProject().getId(),entry.getId()),"visit-due:"+entry.getId()+":"+entry.getNextVisitDate()+":"+user.getId(),false);}
 public void financialReminder(FinancialInstallment installment){var entry=installment.getEntry();var project=entry.getProject();var user=project==null?entry.getCreatedBy():project.getResponsibleUser();if(user==null)return;boolean income=entry.getType()==FinancialEntryType.RECEIVABLE;send(entry.getTenant().getId(),user.getId(),income?NotificationType.RECEIVABLE_DUE_SOON:NotificationType.PAYABLE_DUE_SOON,NotificationCategory.FINANCIAL,NotificationPriority.NORMAL,income?"Recebimento próximo":"Pagamento próximo",entry.getDescription()+" vence em breve.",NotificationSourceType.CALENDAR_EVENT,installment.getId(),"/app/financial","financial-due:"+installment.getId()+":"+installment.getDueDate()+":"+user.getId(),false);}
 private void send(UUID tenant,UUID recipient,NotificationType type,NotificationCategory category,NotificationPriority priority,String title,String message,NotificationSourceType source,UUID sourceId,String action,String key,boolean mandatory){events.publish(new NotificationRequest(tenant,recipient,type,category,priority,title,message,source,sourceId,action,key,mandatory,null,null));}}
